pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 ether, 1000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // reference invariant already holds after deposit
        // drive c through withdrawAll
        vm.prank(actor);
        c.withdrawAll();

        // General rule: the tracked balance always equals the contract's actual ether balance.
        // In P: balance = amount - amount = 0 and real balance = 0. Holds.
        // In M: balance stays amount while real balance = 0. Violated.
        assertTrue(c.balance() == address(c).balance);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // keep the domain wide: any nonzero, sendable amount
        vm.assume(amount > 0 && amount < address(this).balance / 2 + 1 ether);
        amount = bound(amount, 1 wei, 100 ether);

        // adversarial counterparty: a re-entrant caller that, while c is
        // sending it ether, calls back into c.withdrawAll() and c.deposit()
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // fund the attacker, let it drive c through deposit + withdrawAll
        vm.deal(address(attacker), amount);
        attacker.attack(amount);

        // General rule: after a complete deposit/withdrawAll cycle driven by a
        // re-entrant counterparty, c must hold no ether — every credited wei
        // was paid out exactly once, and re-entrant withdrawals pay nothing
        // extra. The reference contract satisfies this for every input.
        assertTrue(address(c).balance == 0);
    }
}

contract ReentrantAttacker {
    C c;
    bool reentered;

    constructor(C _c) { c = _c; }

    function attack(uint256 amount) external payable {
        c.deposit{value: amount}();
        c.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-entrant attempt: credit was already zeroed before the send,
            // so this must be a no-op that transfers nothing further
            c.withdrawAll();
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker();
        attacker.setTarget(c);
    }

    function testFuzz_property(uint256 amount, uint256 reAmt) public {
        bound(amount, 1, 100 ether);
        bound(reAmt, 0, 10 ether);

        attacker.setRedeposit(reAmt);
        vm.deal(address(attacker), amount + reAmt + 1 ether);

        // attacker deposits `amount` into c
        attacker.doDeposit(amount);

        // drive c through withdrawAll; during the external send the attacker
        // re-enters deposit(reAmt) and then withdrawAll() again
        bool ok;
        try attacker.doWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract conserves ether: after the cycle every
        // deposited unit has been paid back out through the (possibly
        // re-entrant) withdrawal path, so c holds exactly zero ether.
        assertTrue(ok && address(c).balance == 0);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 reDepositAmount;
    bool reentered;

    function setTarget(C t) external { target = t; }
    function setRedeposit(uint256 a) external { reDepositAmount = a; }

    function doDeposit(uint256 amt) external {
        target.deposit{value: amt}();
    }

    function doWithdrawAll() external {
        target.withdrawAll();
    }

    receive() external payable {
        if (!reentered && reDepositAmount > 0) {
            reentered = true;
            target.deposit{value: reDepositAmount}();
            target.withdrawAll();
            reentered = false;
        }
    }
}
